// Example 1:
// The ID for Good Health Hospital was assigned by the Community Health and Hospitals enterprise’s Hospital Master and was first issued at the Central Offices.
// Good Health Hospital^L^716^9^M10^&Hospital Master.Community Health and Hospitals&L^XX^&Central Offices.Community Health and Hospitals&L^A
//
// Example 2:
// Good Health Hospital has another ID that was issued by CMS. Assigning Authority, CMS, values only the first HD component, an IS data type and assigning facility is not relevant. This information might be transmitted accordingly:
// Good Health Hospital^L^4544^3^M10^CMS^XX^^A
type XON struct {
	OrganizationName         ST  `hl7:"1"`
	OrganizationNameTypeCode CWE `hl7:"2"`
	IdNumber                 ST  `hl7:"3"`
	IdentifierCheckDigit     NM  `hl7:"4"`
	CheckDigitScheme         ID  `hl7:"5"`
	AssigningAuthority       HD  `hl7:"6"`
	IdentifierTypeCode       ID  `hl7:"7"`
	AssigningFacility        HD  `hl7:"8"`
	NameRepresentationCode   ID  `hl7:"9"`
	OrganizationIdentifier   ST  `hl7:"10"`
}

func NewXON() *XON {
	return &XON{}
}

func (d *XON) Validate() error {

	if (d.OrganizationNameTypeCode != CWE{}) {
		if err := d.OrganizationNameTypeCode.Validate(); err != nil {
			return fmt.Errorf("XON.OrganizationNameTypeCode: %w", err)
		}
	}

	if (d.AssigningAuthority != HD{}) {
		if err := d.AssigningAuthority.Validate(); err != nil {
			return fmt.Errorf("XON.AssigningAuthority: %w", err)
		}
	}

	if (d.AssigningFacility != HD{}) {
		if err := d.AssigningFacility.Validate(); err != nil {
			return fmt.Errorf("XON.AssigningFacility: %w", err)
		}
	}

	return nil
}

func (d *XON) SetOrganizationName(v string) *XON {
	d.OrganizationName = ST(v)
	return d
}

func (d *XON) SetOrganizationNameTypeCode(v CWE) *XON {
	d.OrganizationNameTypeCode = v
	return d
}

func (d *XON) SetIdNumber(v string) *XON {
	d.IdNumber = ST(v)
	return d
}

func (d *XON) SetIdentifierCheckDigit(v string) *XON {
	d.IdentifierCheckDigit = NM(v)
	return d
}

func (d *XON) SetCheckDigitScheme(v string) *XON {
	d.CheckDigitScheme = ID(v)
	return d
}

func (d *XON) SetAssigningAuthority(v HD) *XON {
	d.AssigningAuthority = v
	return d
}

func (d *XON) SetIdentifierTypeCode(v string) *XON {
	d.IdentifierTypeCode = ID(v)
	return d
}

func (d *XON) SetAssigningFacility(v HD) *XON {
	d.AssigningFacility = v
	return d
}

func (d *XON) SetNameRepresentationCode(v string) *XON {
	d.NameRepresentationCode = ID(v)
	return d
}

func (d *XON) SetOrganizationIdentifier(v string) *XON {
	d.OrganizationIdentifier = ST(v)
	return d
}

// XPN - Extended Person Name
// Note: Replaces PN data type as of v 2.3.
//
// Example 1: Adam A. Everyman III PhD
// |Everyman^Adam^A^III^DR^^L^^^^^^^PHD|
//
// Example 2: Ludwig van Beethoven
// |Beethoven&van^Ludwig^^^^^L|
//
// Example 3: Hermann Egon Mayer zur alten Schildesche
// |Mayer^Hermann^Egon^zur alten Schildesche|
type XPN struct {
	FamilyName                                  FN  `hl7:"1"`
	GivenName                                   ST  `hl7:"2"`
	SecondAndFurtherGivenNamesOrInitialsThereof ST  `hl7:"3"`
	SuffixEGJrOrIii                             ST  `hl7:"4"`
	PrefixEGDr                                  ST  `hl7:"5"`
	DegreeEGMd                                  ST  `hl7:"6"`
	NameTypeCode                                ID  `hl7:"7"`
	NameRepresentationCode                      ID  `hl7:"8"`
	NameContext                                 CWE `hl7:"9"`
	NameValidityRange                           ST  `hl7:"10"`
	NameAssemblyOrder                           ID  `hl7:"11"`
	EffectiveDate                               DTM `hl7:"12"`
	ExpirationDate                              DTM `hl7:"13"`
	ProfessionalSuffix                          ST  `hl7:"14"`
	CalledBy                                    ST  `hl7:"15"`
}

func NewXPN() *XPN {
	return &XPN{}
}

func (d *XPN) Validate() error {

	if (d.FamilyName != FN{}) {
		if err := d.FamilyName.Validate(); err != nil {
			return fmt.Errorf("XPN.FamilyName: %w", err)
		}
	}

	if (d.NameContext != CWE{}) {
		if err := d.NameContext.Validate(); err != nil {
			return fmt.Errorf("XPN.NameContext: %w", err)
		}
	}

	return nil
}

