// XTN - Extended Telecommunication Number
// Example 1: A Work fax number
// ^WPN^FX^^^734^6777777
//
// Example 2: Telephone number with extension
// ^WPN^PH^^^734^6777777^1
//
// Example 4: home e-mail address. In this example, assume that a person has a primary home e-mail address such as someone@somewhere.com.  The components would be:
// ^PRN^Internet^someone@somewhere.com
type XTN struct {
	TelephoneNumber                   ST  `hl7:"1"`
	TelecommunicationUseCode          ID  `hl7:"2"`
	TelecommunicationEquipmentType    ID  `hl7:"3"`
	CommunicationAddress              ST  `hl7:"4"`
	CountryCode                       SNM `hl7:"5"`
	AreaCityCode                      SNM `hl7:"6"`
	LocalNumber                       SNM `hl7:"7"`
	Extension                         SNM `hl7:"8"`
	AnyText                           ST  `hl7:"9"`
	ExtensionPrefix                   ST  `hl7:"10"`
	SpeedDialCode                     ST  `hl7:"11"`
	UnformattedTelephoneNumber        ST  `hl7:"12"`
	EffectiveStartDate                DTM `hl7:"13"`
	ExpirationDate                    DTM `hl7:"14"`
	ExpirationReason                  CWE `hl7:"15"`
	ProtectionCode                    CWE `hl7:"16"`
	SharedTelecommunicationIdentifier EI  `hl7:"17"`
	PreferenceOrder                   NM  `hl7:"18"`
}

func NewXTN() *XTN {
	return &XTN{}
}

func (d *XTN) Validate() error {

	if string(d.TelecommunicationEquipmentType) == "" {
		return fmt.Errorf("XTN.TelecommunicationEquipmentType is required")
	}

	if (d.ExpirationReason != CWE{}) {
		if err := d.ExpirationReason.Validate(); err != nil {
			return fmt.Errorf("XTN.ExpirationReason: %w", err)
		}
	}

	if (d.ProtectionCode != CWE{}) {
		if err := d.ProtectionCode.Validate(); err != nil {
			return fmt.Errorf("XTN.ProtectionCode: %w", err)
		}
	}

	if (d.SharedTelecommunicationIdentifier != EI{}) {
		if err := d.SharedTelecommunicationIdentifier.Validate(); err != nil {
			return fmt.Errorf("XTN.SharedTelecommunicationIdentifier: %w", err)
		}
	}

	return nil
}

func (d *XTN) SetTelephoneNumber(v string) *XTN {
	d.TelephoneNumber = ST(v)
	return d
}

